uniform sampler2D uPreviousFrame;
uniform vec2 uMouse;
uniform float uTime;
uniform float uDeltaTime;
uniform vec2 uResolution;

float rand(vec2 n) {
    return fract(sin(dot(n, vec2(12.9898, 4.1414))) * 43758.5453);
}

float noise(vec2 p) {
    vec2 ip = floor(p);
    vec2 u = fract(p);
    u = u * u * (3.0 - 2.0 * u);

    float res = mix(
        mix(rand(ip), rand(ip + vec2(1.0, 0.0)), u.x),
        mix(rand(ip + vec2(0.0, 1.0)), rand(ip + vec2(1.0, 1.0)), u.x),
        u.y
    );

    return res * res;
}

void mainImage(const in vec4 inputColor, const in vec2 uv, out vec4 outputColor) {
    vec2 screenMouse = uMouse * uResolution;
    vec2 screenUv = uv * uResolution;

    vec2 ripple = screenUv - screenMouse;
    float dist = length(ripple);

    float hoverRadius = 100.0;
    float smudgePower = 0.05;
    float noiseScale = 15.0;

    if (dist < hoverRadius) {
        float falloff = smoothstep(hoverRadius, 0.0, dist);

        float n = noise(uv * noiseScale + uTime * 2.0);

        vec2 direction = normalize(ripple);
        vec2 displacement = (direction + vec2(n)) * smudgePower * falloff * 0.1;

        vec4 smudgedColor = texture2D(uPreviousFrame, uv - displacement);

        // stronger black push
        smudgedColor.rgb = mix(smudgedColor.rgb, vec3(0.0), falloff);

        // ✅ FORCE FULL OPACITY
        outputColor = vec4(smudgedColor.rgb, 1.0);
    } else {
        outputColor = inputColor;
    }
}

