float rand(vec2 n) { return fract(sin(dot(n, vec2(12.9898, 4.1414))) * 43758.5453); }
float noise(vec2 p) {
    vec2 ip = floor(p);
    vec2 u = fract(p);
    u = u * u * (3.0 - 2.0 * u);
    float res = mix(mix(rand(ip), rand(ip + vec2(1.0, 0.0)), u.x),
                    mix(rand(ip + vec2(0.0, 1.0)), rand(ip + vec2(1.0, 1.0)), u.x), u.y);
    return res * res;
}

uniform float rippleDensity;
uniform float rippleSpeed;
uniform float rippleMagnitude;
uniform float rippleFalloff;
uniform float displacementStrength;
uniform float rippleSize;

void mainImage(const in vec4 inputColor, const in vec2 uv, out vec4 outputColor) {
    vec2 rippleCenter = uMouse;
    float dist = distance(uv, rippleCenter);
    float ripple = cos(dist * rippleDensity - uTime * rippleSpeed) * rippleMagnitude / (dist * rippleFalloff + rippleSize);
    vec2 displacedUv = uv + normalize(uv - rippleCenter) * ripple * (displacementStrength - dist * 0.5);
    outputColor = texture2D(uPreviousFrame, displacedUv);
}
